// 每个结点单独维护一条“孩子链表”
struct TreeNode {
    char data;                  // 如 'A'
    struct ChildNode* children; // 指向第一个孩子链表结点
};

struct ChildNode {
    struct TreeNode* child; // 指向实际孩子
    struct ChildNode* next; // 指向下一个兄弟
};

// 例：根 A 有孩子 B、C、D；B 有孩子 E、F
// A.children -> [B] -> [C] -> [D]
// B.children -> [E] -> [F]

// 把同一双亲的孩子串成“右兄弟链”，结点本身兼作链结点
struct Node {
    char data;                 // 如 'A'
    struct Node* leftChild;    // 第一个孩子
    struct Node* rightSibling; // 下一个兄弟
};

// 同一棵树的 LCRS 表示
// A.leftChild = B
// B.rightSibling = C;  C.rightSibling = D
// B.leftChild = E;     E.rightSibling = F

// 本质：把多叉树“拧成”二叉树形状

