# 二叉树：每个节点是 {'v': 值, 'l': 左子树, 'r': 右子树}
tree = {
    'v': 5.0,
    'l': {'v': 3.5, 'l': {'v': 2.8}, 'r': {'v': 4.5}},
    'r': {'v': 7.0, 'l': {'v': 6.2}, 'r': {'v': 7.5}}
}

result = []

def walk(node):
    if node is None:
        return
    # 前序：先访问根，再遍历左、右子树
    result.append({'x': node['v'], 'y': len(result)})
    walk(node['l'])
    walk(node['r'])

walk(tree)

starter.js:
const tree = {
  v: 5.0,
  l: { v: 3.5, l: { v: 2.8 }, r: { v: 4.5 } },
  r: { v: 7.0, l: { v: 6.2 }, r: { v: 7.5 } }
};

const result = [];

function walk(node) {
  if (!node) return;
  // 前序：先访问根，再遍历左、右子树
  result.push({ x: node.v, y: result.length });
  walk(node.l);
  walk(node.r);
}

walk(tree);
